  function playerClick(event){if(!event.isTrusted||event.composedPath().includes(host)||event.composedPath().includes(nativeButton)||event.composedPath().includes(quickAdd))return;if(menuOpen){openMenu(false);event.preventDefault();event.stopImmediatePropagation();return;}if(inRemoteMode()){event.preventDefault();event.stopImmediatePropagation();if(event.type==='click')run('toggle',{},event);}}
