        if(p.bytes)bits.push(NoYouPubI18n.t('{{0}} Mo préparés').replace('{{0}}',(p.bytes/1048576).toFixed(1)));
        if(p.started)bits.push(NoYouPubI18n.t('{{0}} écoulées').replace('{{0}}',clock(Date.now()/1000-p.started)));
